package com.estoqueinteligente.supplier;import java.time.Instant;public class SupplierResponse{private final Long id;private final String name,phone,email,contactPerson,notes;private final Instant createdAt,updatedAt;public SupplierResponse(Supplier s){id=s.getId();name=s.getName();phone=s.getPhone();email=s.getEmail();contactPerson=s.getContactPerson();notes=s.getNotes();createdAt=s.getCreatedAt();updatedAt=s.getUpdatedAt();}public Long getId(){return id;}public String getName(){return name;}public String getPhone(){return phone;}public String getEmail(){return email;}public String getContactPerson(){return contactPerson;}public String getNotes(){return notes;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
